steps.command:
$origin = git config --get remote.origin.url 2>$null
if ($origin) { $origin = $origin -replace '^git@github\.com:', 'https://github.com/' -replace '\.git$', '' }
$dirty = git status --porcelain 2>$null
if ($origin -ne "https://github.com/Blueturboguy07/nut-ai" -or $dirty) {
  Write-Host "~/nut-ai already exists and is not a clean copy of this app's source. Move or rename that folder, then press Try again."
  exit 1
}
git checkout dace89160b86de38165a952100860f47f1010177

$jh = [Environment]::GetEnvironmentVariable('JAVA_HOME', 'User')
if ($jh) { $env:JAVA_HOME = $jh }
if ($env:JAVA_HOME) { $env:Path = $env:JAVA_HOME + '\bin;' + $env:Path }
function Get-JavaMajor {
  if ($env:JAVA_HOME -and -not (Test-Path ($env:JAVA_HOME + '\bin\java.exe'))) { return 0 }
  $v = cmd /c "java -version 2>&1" | Out-String
  if ($v -match 'version "1\.(\d+)') { return [int]$Matches[1] }
  if ($v -match 'version "(\d+)') { return [int]$Matches[1] }
  return 0
}
if ((Get-JavaMajor) -lt 17) {
  $root = Join-Path $env:ProgramFiles 'Eclipse Adoptium'
  $jdk = Get-ChildItem $root -Directory -Filter 'jdk-17*' -ErrorAction SilentlyContinue | Select-Object -Last 1
  if (-not $jdk) {
    winget install --id EclipseAdoptium.Temurin.17.JDK -e --source winget --accept-source-agreements --accept-package-agreements
    $jdk = Get-ChildItem $root -Directory -Filter 'jdk-17*' -ErrorAction SilentlyContinue | Select-Object -Last 1
  }
  if ($jdk) {
    $env:JAVA_HOME = $jdk.FullName
    $env:Path = $jdk.FullName + '\bin;' + $env:Path
    [Environment]::SetEnvironmentVariable('JAVA_HOME', $jdk.FullName, 'User')
  }
}
java -version
if ((Get-JavaMajor) -lt 17) { throw 'Java 17 or newer is still missing. Install Temurin 17 from adoptium.net, then run this step again.' }

$jh = [Environment]::GetEnvironmentVariable('JAVA_HOME', 'User')
if ($jh) { $env:JAVA_HOME = $jh; $env:Path = $jh + '\bin;' + $env:Path }
$sdk = $env:ANDROID_HOME
if (-not $sdk) { $sdk = $env:ANDROID_SDK_ROOT }
$sdkDefault = $HOME + '\AppData\Local\Android\Sdk'
if (-not $sdk -and (Test-Path $sdkDefault)) { $sdk = $sdkDefault; $env:ANDROID_HOME = $sdk }
$adb = New-Object System.Diagnostics.ProcessStartInfo ($sdk + '\platform-tools\adb.exe'), 'start-server'
$adb.UseShellExecute = $true
$adb.WindowStyle = 'Hidden'
if ($sdk -and (Test-Path $adb.FileName)) { [System.Diagnostics.Process]::Start($adb).WaitForExit() }
$abis = ''
if ($sdk -and (Test-Path $adb.FileName)) { $abis = & $adb.FileName shell getprop ro.product.cpu.abilist 2>$null }
$abi = @("$abis" -split '[,\s]+' | Where-Object { 'armeabi-v7a', 'arm64-v8a', 'x86', 'x86_64' -contains $_ })[0]
if (-not $abi) { $abi = 'arm64-v8a' }
$env:ORG_GRADLE_PROJECT_reactNativeArchitectures = $abi
$env:GRADLE_OPTS = '-Dorg.gradle.daemon=false'
